import React from 'react';

function MyTickets({ bookings = [], movies = [], showtimes = [], seats = [], rooms = [], currentUser = null, onCancelBooking = null, onCancelOrder = null, onBackHome }) {
  const findShowtime = (id) => showtimes.find(s => s.id === id) || {};
  const findMovie = (movie_id) => movies.find(m => m.id === movie_id) || {};
  const findSeat = (id) => seats.find(s => s.id === id) || {};
  const findRoom = (id) => rooms.find(r => r.id === id) || {};

  // group bookings by original_booking_id (fallback to individual id)
  const groups = bookings.reduce((acc, b) => {
    const key = b.original_booking_id || b.id;
    if (!acc[key]) acc[key] = [];
    acc[key].push(b);
    return acc;
  }, {});

  const groupKeys = Object.keys(groups);

  return (
    <div>
      <div className="d-flex justify-content-between align-items-center mb-3">
        <h3 className="fw-bold mb-0" style={{ color: '#7c3aed' }}>Vé của tôi</h3>
        <button className="btn fw-bold py-2 px-3" style={{ background: '#f3f4f6', borderRadius: 8 }} onClick={onBackHome}>Quay lại trang chủ</button>
      </div>
      <div className="row">
        {bookings.length === 0 && <div className="col-12 text-muted">Bạn chưa có vé nào.</div>}

        {groupKeys.map((gk) => {
          const group = groups[gk];
          const first = group[0];
          const st = findShowtime(first.showtime_id);
          const movie = findMovie(st.movie_id);
          const room = findRoom(st.room_id);
          return (
            <div key={gk} className="col-12 col-md-6 mb-3">
              <div className="card p-3 shadow-sm" style={{ borderRadius: 12 }}>
                <div className="d-flex justify-content-between align-items-start">
                  <div>
                    <div className="fw-bold">{movie.title}</div>
                    <div className="text-secondary small">{st.show_date} • {st.show_time}</div>
                    <div className="mt-2">Phòng: <strong>{room.name || 'Chưa rõ'}</strong></div>
                    <div className="mt-2">Ghế: <strong>{group.map(b => findSeat(b.seat_id).seat_number).join(', ')}</strong></div>
                  </div>
                  <div style={{ textAlign: 'right' }}>
                    <div className="badge" style={{ background: first.paid ? 'linear-gradient(135deg, #7c3aed 0%, #a855f7 100%)' : '#f3f4f6', color: first.paid ? 'white' : '#6b7280', padding: '8px 12px', borderRadius: 8 }}>{first.paid ? 'Đã thanh toán' : 'Chưa thanh toán'}</div>
                    {currentUser && first.user_id === currentUser.id && onCancelOrder && (
                      <div className="mt-3">
                        <button className="btn btn-sm btn-danger" onClick={() => onCancelOrder(first.original_booking_id || gk)}>Hủy đơn</button>
                      </div>
                    )}
                    {currentUser && first.user_id === currentUser.id && onCancelBooking && (
                      <div className="mt-2 small text-muted">Bạn cũng có thể hủy từng ghế bên dưới.</div>
                    )}
                  </div>
                </div>

                {/* optional list of individual seats with per-seat cancel */}
                <div className="mt-3 d-flex gap-2 flex-wrap">
                  {group.map(b => {
                    const seat = findSeat(b.seat_id);
                    return (
                      <div key={b.id} style={{ minWidth: 120 }}>
                        <div className="small text-secondary">{seat.seat_number}</div>
                        {currentUser && b.user_id === currentUser.id && onCancelBooking && (
                          <button className="btn btn-sm btn-outline-danger mt-1" onClick={() => onCancelBooking(b.id)}>Hủy ghế</button>
                        )}
                      </div>
                    );
                  })}
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

export default MyTickets;
